PREV = dict(previous_close=49850.0, previous_volume=127602.0, previous_day="2026-11-25")


def rows(until):
    out = []
    for part in HVM.split("|"):
        hm, *nums = part.split()
        o, h, l, c, v = (float(x) for x in nums)
        stamp = datetime(2026, 11, 26, int(hm[:2]), int(hm[2:]), tzinfo=KST)
        if stamp.strftime("%H:%M") > until:
            break
        out.append(dict(timestamp=stamp.isoformat(), open=o, high=h, low=l, close=c, volume=int(v)))
    return out


def judge(until):
    r = rows(until)
    now = datetime.fromisoformat(r[-1]["timestamp"]) + timedelta(minutes=1, seconds=8)
    return P.evaluate(r, now=now, **PREV)


def bought(res):
    return bool(res and res.get("buy") and res.get("route") == "BOTTOM_MA5")


class V7635DefaultTests(unittest.TestCase):
    def test_switches_on(self):
        self.assertTrue(P.FLOOR_BREAK_RESET)
        self.assertEqual(P.FLOOR_BREAK_TOL, 0.01)
        self.assertTrue(P.FLOOR_REVERSAL_AFTER_LOW)
        self.assertEqual(P.FLOOR_MA5_SETTLE_BARS, 1)          # V7635b 형 결정: 1봉

    def test_1033_touch_is_not_bought(self):
        # 10:33 종가 58,300 vs 1분 MA5 58,280 (20원 걸침), 바닥 59,600은 10:28부터 -1% 넘게 이탈 → 사지 않는다
        self.assertFalse(bought(judge("10:33")))

    def test_old_rule_reproduces_the_wrong_buy(self):
        with mock.patch.object(P, "FLOOR_BREAK_RESET", False), \
             mock.patch.object(P, "FLOOR_REVERSAL_AFTER_LOW", False), \
             mock.patch.object(P, "FLOOR_MA5_SETTLE_BARS", 1):
            r = judge("10:33")
            self.assertTrue(bought(r))
            self.assertEqual(r["floor_index"], 126)          # 10:17 바닥을 그대로 재사용했던 것

    def test_1019_one_bar_above_ma5_buys_with_default(self):
        r = judge("10:19")                                   # 바닥 10:17 직후, 10:18 밑꼬리 뒤 10:19 종가 60,200 ≥ MA5 60,080
        self.assertTrue(bought(r))
        self.assertIn("5선안착", r["reason"])

    def test_1019_not_bought_when_two_bars_required(self):
        with mock.patch.object(P, "FLOOR_MA5_SETTLE_BARS", 2):  # 10:18 종가 59,900 < MA5 60,180 → 1봉만 위
            r = judge("10:19")
            self.assertEqual((r["route"], r["buy"]), ("FLOOR", False))

    def test_1020_two_bars_settled_after_floor(self):
        with mock.patch.object(P, "FLOOR_MA5_SETTLE_BARS", 2):  # 10:19·10:20 종가 둘 다 1분 MA5 위
            r = judge("10:20")
        self.assertTrue(bought(r))
        self.assertIn("5선안착", r["reason"])
        self.assertEqual((r["flush_index"], r["floor_index"]), (125, 126))

    def test_small_undercut_keeps_floor(self):
        # 10:18 저가 59,500 은 바닥 59,600 보다 1호가 아래지만 1% 안 → 바닥 유지(매수직전)
        r = judge("10:27")
        self.assertEqual((r["route"], r["buy"], r["floor_index"]), ("FLOOR", False, 126))

    def test_floor_break_drops_the_episode(self):
        for hm in ("10:28", "10:30", "10:32", "10:33"):  # 10:28 저가 59,000 < 59,600×0.99
            r = judge(hm)
            self.assertFalse(r and r.get("route") in ("FLOOR", "BOTTOM_MA5") and r.get("floor_index") == 126, hm)

    def test_ma5_settled_helper(self):
        mk = lambda closes: [dict(close=float(c)) for c in closes]
        self.assertTrue(P._ma5_settled(mk([10, 10, 10, 10, 11, 12]), 2))
        self.assertFalse(P._ma5_settled(mk([10, 10, 10, 10, 9, 12]), 2))   # 직전봉이 5선 아래
        self.assertTrue(P._ma5_settled(mk([10, 10, 10, 10, 9, 12]), 1))


